def standard_from_mask(mask):
    s=''.join(ch for bit,ch in zip(mask,rights_letters) if bit)
    return s if s else '-'

def fixed_from_mask(mask):
    return ''.join(ch if bit else '-' for bit,ch in zip(mask,rights_letters))

